static LONG SofSpeakerListenSample(ULONG frame, BOOLEAN louder)
{
    return (LONG)SofSpeakerListenPcm[frame % 6144] * (louder ? 16384 : 8192);
}
static VOID SofSpeakerFillListenSamples(LONG *samples, ULONG channel, BOOLEAN louder)
{
    ULONG i;
    for (i=0;i<6144;++i) {
        samples[2*i] = channel == 0 ? SofSpeakerListenSample(i,louder) : 0;
        samples[2*i+1] = channel == 1 ? SofSpeakerListenSample(i,louder) : 0;
    }
}
static BOOLEAN SofSpeakerListenSamplesValid(const LONG *samples, ULONG channel, BOOLEAN louder)
{
    ULONG i;
    if (samples == NULL || channel > 1) return FALSE;
    for (i=0;i<6144;++i)
        if (samples[2*i+channel] != SofSpeakerListenSample(i,louder) || samples[2*i+1-channel] != 0)
            return FALSE;
    return TRUE;
}
